type Period = 'weekly' | 'monthly' | 'two_months' | 'three_months' | 'six_months' | 'annual' | 'lifetime' | 'consumable'

export interface ZzzStoreProduct {
  identifier: string
  title: string
  description: string
  price: number
  priceString: string
  currencyCode: string
  /** ISO 8601 (P1M, P1Y…) ou null pour un achat unique. */
  subscriptionPeriod: string | null
  introPrice: { price: number; priceString: string; period: string; cycles: number } | null
  productCategory: 'SUBSCRIPTION' | 'NON_SUBSCRIPTION'
}

export interface ZzzPackage {
  identifier: string
  packageType: string
  offeringIdentifier: string
  product: ZzzStoreProduct
}

export interface ZzzOffering {
  identifier: string
  availablePackages: ZzzPackage[]
  weekly: ZzzPackage | null
  monthly: ZzzPackage | null
  twoMonth: ZzzPackage | null
  threeMonth: ZzzPackage | null
  sixMonth: ZzzPackage | null
  annual: ZzzPackage | null
  lifetime: ZzzPackage | null
}

export interface ZzzEntitlement {
  identifier: string
  isActive: boolean
  productIdentifier: string | null
  expirationDate: string | null
  reason: string
  /** false = résilié : l'accès reste ouvert jusqu'à expirationDate puis s'arrête. null = inconnu. */
  willRenew?: boolean | null
  /** Offre du prochain renouvellement quand elle diffère (passage à l'annuel programmé…). null sinon. */
  renewalProductIdentifier?: string | null
  /**
   * Accès à vie détenu ET un abonnement continue de se renouveler (Apple ne l'arrête jamais
   * tout seul) : l'app propose de le résilier via manageSubscriptions(). null sinon.
   */
  redundantSubscriptionProductIdentifier?: string | null
  /** Rang du niveau dans ZZZ_PAYWALL.tiers (0 = le plus bas). null hors échelle. */
  level?: number | null
  /** Niveau supérieur qui ouvre celui-ci (Premium ouvre Pro). null s'il est détenu en propre. */
  grantedBy?: string | null
}

export interface CustomerInfo {
  originalAppUserId: string
  entitlements: { active: Record<string, ZzzEntitlement>; all: Record<string, ZzzEntitlement> }
  requestDate: string
}

export type PurchasesPackage = ZzzPackage
