export interface ZzzPurchaseResult {
  /** L'achat est allé au bout (≠ entitlement débloqué : vérifier entitlementActive). */
  success: boolean
  /** L'accès du produit acheté (son palier) est actif — c'est CE champ qui débloque. */
  entitlementActive: boolean
  /** L'utilisateur a fermé la feuille de paiement : ne JAMAIS afficher d'erreur dans ce cas. */
  cancelled: boolean
  /** Produit réellement acheté : sert à créditer un pack consommable (pièces, vies). */
  productIdentifier?: string
  /** Identifiant unique de la transaction : créditer un pack UNE seule fois par transaction. */
  transactionIdentifier?: string
  /** Raison d'un échec, pour le diagnostic (jamais à afficher telle quelle). */
  error?: string
  /**
   * Changement d'offre PROGRAMMÉ, rien n'est payé maintenant : Apple garde l'abonnement en cours
   * et passe à productIdentifier au renouvellement (date, ISO). Ne JAMAIS afficher « achat
   * réussi » : afficher « Passage à <offre> prévu le <date> ».
   */
  scheduledChange?: { productIdentifier: string; date: string | null }
}

export interface ZzzRefundResult {
  /** Demande transmise à Apple, qui décide (jusqu'à 48 h). L'accès ne se coupe que si Apple rembourse. */
  submitted: boolean
  /** L'utilisateur a fermé la fenêtre d'Apple : ne JAMAIS afficher d'erreur dans ce cas. */
  cancelled: boolean
  /** Raison d'un échec, pour le diagnostic (jamais à afficher telle quelle). */
  error?: string
}

/** Un identifiant du catalogue, ou le package entier (recommandé). */
