const API_BASE = (ZZZ_PAYWALL.bloxksPayApiBase || 'https://pay.bloxks.app').replace(/\/$/, '')
const API_KEY = ZZZ_PAYWALL.bloxksPayPublicKey || ''
const IS_WEB = Platform.OS === 'web'
const IS_EXPO_GO = Constants.appOwnership === 'expo'
const IS_ANDROID = Platform.OS === 'android'
const FAIL_OPEN_MS = 7 * 24 * 60 * 60 * 1000
// Achat : au plus 90 s d'attente d'une livraison StoreKit ; et dès que la feuille Apple se ferme
// (retour au premier plan), 15 s de plus puis relecture des achats : jamais de roue sans fin.
const PURCHASE_TIMEOUT_MS = 90 * 1000
const PURCHASE_NET_MS = 15 * 1000
// Aperçu web : un suffixe différent → client vierge (anciennes réinitialisations conservées).
const STORAGE_PREFIX = 'bloxkspay:v1:' + (IS_WEB && ZZZ_PAYWALL.bloxksPayPreviewSuffix ? ZZZ_PAYWALL.bloxksPayPreviewSuffix + ':' : '')
const PERIOD_ISO: Record<string, string> = { weekly: 'P1W', monthly: 'P1M', two_months: 'P2M', three_months: 'P3M', six_months: 'P6M', annual: 'P1Y' }
const PACKAGE_TYPE: Record<string, string> = { weekly: 'WEEKLY', monthly: 'MONTHLY', two_months: 'TWO_MONTH', three_months: 'THREE_MONTH', six_months: 'SIX_MONTH', annual: 'ANNUAL', lifetime: 'LIFETIME', consumable: 'CUSTOM' }
const PACKAGE_ID: Record<string, string> = { weekly: '$rc_weekly', monthly: '$rc_monthly', two_months: '$rc_two_month', three_months: '$rc_three_month', six_months: '$rc_six_month', annual: '$rc_annual', lifetime: '$rc_lifetime' }
// Google Play : base plan créé par Bloxks pour chaque cadence, et offre d'essai gratuit
// (mêmes valeurs que la création du catalogue Play, playstore/subscription-catalog.ts).
const PLAY_BASE_PLAN: Record<string, string> = { weekly: 'weekly', monthly: 'monthly', two_months: 'two-monthly', three_months: 'quarterly', six_months: 'semiannual', annual: 'annual' }
const PLAY_TRIAL_OFFER = 'free-trial'
// Android : le Play Store (gestion d'abonnement, code promo) s'ouvre HORS de l'app ; on
// relit les droits à son retour, au plus tard après ce délai.
const STORE_RETURN_MS = 5 * 60 * 1000

