function uuid(): string {
  const hex = '0123456789abcdef'
  let out = ''
  for (let i = 0; i < 36; i++) {
    if (i === 8 || i === 13 || i === 18 || i === 23) out += '-'
    else if (i === 14) out += '4'
    else if (i === 19) out += hex[(Math.random() * 4) | 8]
    else out += hex[(Math.random() * 16) | 0]
  }
  return out
}

async function readStore(key: string): Promise<string | null> {
  try {
    if (IS_WEB && typeof localStorage !== 'undefined') return localStorage.getItem(STORAGE_PREFIX + key)
    return await AsyncStorage.getItem(STORAGE_PREFIX + key)
  } catch {
    return null
  }
}

async function writeStore(key: string, value: string): Promise<void> {
  try {
    if (IS_WEB && typeof localStorage !== 'undefined') localStorage.setItem(STORAGE_PREFIX + key, value)
    else await AsyncStorage.setItem(STORAGE_PREFIX + key, value)
  } catch {
    /* stockage indisponible : on garde la valeur en mémoire */
  }
}

/**
 * Identifiant client : celui donné par identifyPlayer, sinon un identifiant anonyme stable.
 * Une seule lecture en vol : deux appels simultanés au premier lancement (achat relivré au
 * démarrage + écran) donnaient deux identifiants, donc deux « clients » pour un même téléphone.
 */
async function currentUserId(): Promise<string> {
  if (appUserId) return appUserId
  if (!userIdPromise) {
    userIdPromise = (async () => {
      const saved = await readStore('user')
      if (saved) {
        appUserId = appUserId || saved
        return appUserId
      }
      const anon = 'anon_' + uuid()
      appUserId = appUserId || anon
      await writeStore('user', appUserId)
      return appUserId
    })()
    userIdPromise.then(() => { userIdPromise = null }, () => { userIdPromise = null })
  }
  return userIdPromise
}

/** appAccountToken StoreKit (UUID), stable par installation : relie un reçu Apple à ce client. */
async function currentAccountToken(): Promise<string> {
  if (accountToken) return accountToken
  if (!accountTokenPromise) {
    accountTokenPromise = (async () => {
      const saved = await readStore('token')
      accountToken = accountToken || saved || uuid()
      if (!saved) await writeStore('token', accountToken)
      return accountToken
    })()
    accountTokenPromise.then(() => { accountTokenPromise = null }, () => { accountTokenPromise = null })
  }
  return accountTokenPromise
}

/**
 * Journal de diagnostic côté BloxksPay (Journal du tableau de bord) : étapes d'un achat,
 * sans donnée personnelle. Jamais bloquant, jamais dans l'aperçu web.
 */
function diag(kind: string, detail?: Record<string, unknown>): void {
  if (IS_WEB || !API_KEY) return
  currentUserId()
    .then((userId) => api('/v1/sdk/events', { method: 'POST', body: { appUserId: userId, events: [{ kind: kind, at: new Date().toISOString(), detail: detail || {} }] } }))
    .catch(() => {})
}

/** Termine l'achat en cours (une seule fois) et arrête ses minuteries. */
function settlePending(result: ZzzPurchaseResult, outcome: string): void {
  if (!pending) return
  const p = pending
  pending = null
  clearTimeout(p.timer)
  if (p.net) clearTimeout(p.net)
  diag('purchase_settled', { sku: p.sku, outcome: outcome, afterMs: Date.now() - p.startedAt, success: result.success, entitlementActive: result.entitlementActive })
  p.resolve(result)
}

/**
 * Règle l'achat en cours d'après une relecture des achats (Apple + BloxksPay) : droit actif →
 * achat réussi, sinon échec clair (inactiveError). Sert au filet et à « déjà acheté ».
 */
async function settleFromRestore(p: NonNullable<typeof pending>, outcome: string, inactiveError: string): Promise<void> {
  let active = false
  try {
    const info = await sendRestore()
    active = info ? productAccessActive(info, p.sku) : false
  } catch {
    /* hors ligne : échec clair ci-dessous */
  }
  if (pending !== p) return
  if (active) settlePending({ success: true, entitlementActive: true, cancelled: false, productIdentifier: p.sku }, outcome + '_active')
  else settlePending({ success: false, entitlementActive: false, cancelled: false, error: inactiveError }, outcome + '_inactive')
}

/** Une vérification BloxksPay est en cours pour l'achat en attente : c'est elle qui le réglera. */
function verifyingPending(p: NonNullable<typeof pending>): boolean {
  for (const productId of verifying.values()) if (settlesPending(p.sku, productId)) return true
  return false
}

/**
 * Filet de sécurité : la feuille Apple s'est fermée (retour au premier plan) sans qu'aucune
 * livraison StoreKit n'arrive dans les 15 s (déjà abonné, feuille fermée sans erreur, livraison
 * perdue). On relit alors les achats chez Apple et BloxksPay : droit actif → achat réussi,
 * sinon échec clair. Un pack (consommable) reste attendu : rien à relire. Si une vérification
 * est déjà en vol (serveur lent), on la laisse conclure : jamais deux verdicts.
 */
function armPurchaseNet(): void {
  if (!pending || pending.net || isConsumable(pending.sku)) return
  const p = pending
  p.net = setTimeout(() => {
    if (pending !== p) return
    p.net = null
    if (verifyingPending(p)) return
    void settleFromRestore(p, 'net', 'no_delivery')
  }, PURCHASE_NET_MS)
}

/** Un seul écouteur d'état de l'app : relecture des droits au retour, et filet d'achat. */
function watchAppState(): void {
  if (watchingAppState || IS_WEB) return
  watchingAppState = true
  AppState.addEventListener('change', (state) => {
    if (state !== 'active') return
    Array.from(foregroundWaiters).forEach((done) => done())
    if (pending) armPurchaseNet()
    // Android : un achat en attente (espèces, validation) peut aboutir hors de l'app.
    if (IS_ANDROID && !pending && iap && connected) void replayAndroid(iap)
    if (subscribers.size > 0 || unverified.size > 0) getCustomerInfo().catch(() => {})
  })
}

/** Android : attend le retour dans l'app (Play Store ouvert à côté), au plus maxMs. */
function untilForeground(maxMs: number): Promise<void> {
  watchAppState()
  return new Promise((resolve) => {
    let timer: ReturnType<typeof setTimeout> | null = null
    const done = () => {
      foregroundWaiters.delete(done)
      if (timer) clearTimeout(timer)
      resolve()
    }
    foregroundWaiters.add(done)
    timer = setTimeout(done, maxMs)
  })
}

function infoFrom(entitlements: Record<string, ZzzEntitlement>, userId: string): CustomerInfo {
  const active: Record<string, ZzzEntitlement> = {}
  for (const key of Object.keys(entitlements)) if (entitlements[key].isActive) active[key] = entitlements[key]
  return { originalAppUserId: userId, entitlements: { active: active, all: entitlements }, requestDate: new Date().toISOString() }
}

function publish(info: CustomerInfo): void {
  // Réponse d'une ancienne identité (identifyPlayer pendant une lecture en vol) : ignorée.
  if (appUserId && info.originalAppUserId !== appUserId) return
  current = info
  subscribers.forEach((cb) => {
    try {
      cb(info)
    } catch {
      /* un abonné défaillant ne bloque pas les autres */
    }
  })
}

async function saveCache(userId: string, entitlements: Record<string, ZzzEntitlement>): Promise<void> {
  const entry: CacheEntry = { entitlements: entitlements, verifiedAt: Date.now() }
  await writeStore('cache:' + userId, JSON.stringify(entry))
}

/** Droits mémorisés : un droit actif reste ouvert au plus 7 jours après sa dernière vérification. */
async function cachedInfo(userId: string): Promise<CustomerInfo | null> {
  const raw = await readStore('cache:' + userId)
  if (!raw) return null
  try {
    const entry = JSON.parse(raw) as CacheEntry
    const fresh = Date.now() - entry.verifiedAt < FAIL_OPEN_MS
    const entitlements: Record<string, ZzzEntitlement> = {}
    for (const key of Object.keys(entry.entitlements || {})) {
      const e = entry.entitlements[key]
      const notExpired = !e.expirationDate || Date.parse(e.expirationDate) > Date.now() - FAIL_OPEN_MS
      entitlements[key] = { ...e, isActive: e.isActive && fresh && notExpired }
    }
    return infoFrom(entitlements, userId)
  } catch {
    return null
  }
}

/** Droits lus dans une réponse BloxksPay. Sans bloc entitlements, ce n'est pas une réponse de BloxksPay : traité comme une panne. */
function entitlementsFromServer(body: any): Record<string, ZzzEntitlement> {
  const out: Record<string, ZzzEntitlement> = {}
  const src = body && body.entitlements
  if (!src || typeof src !== 'object') throw new Error('Bloxks Pay invalid response')
  for (const key of Object.keys(src)) {
    const e = src[key] || {}
    out[key] = { identifier: key, isActive: e.active === true, productIdentifier: e.productId || null, expirationDate: e.expiresAt || null, reason: String(e.reason || ''), willRenew: typeof e.willRenew === 'boolean' ? e.willRenew : null, renewalProductIdentifier: e.renewalProductId && e.renewalProductId !== e.productId ? String(e.renewalProductId) : null, redundantSubscriptionProductIdentifier: e.redundantSubscriptionProductId ? String(e.redundantSubscriptionProductId) : null, level: typeof e.level === 'number' ? e.level : null, grantedBy: e.grantedBy ? String(e.grantedBy) : null }
  }
  return out
}

// ------------------------------------------------------------- niveaux -----

/** Échelle des niveaux, du plus bas au plus haut. Une app à un seul niveau : [entitlementId]. */
function tierList(): string[] {
  const t = (ZZZ_PAYWALL as unknown as { tiers?: readonly string[] }).tiers
  return t && t.length > 0 ? t.slice() : [ZZZ_PAYWALL.entitlementId]
}

/** Niveau ouvert par un produit (le plus bas par défaut), null pour un pack ou un produit inconnu. */
function productTier(productId: string | null | undefined): string | null {
  const products = ZZZ_PAYWALL.products as Record<string, { period: Period; access?: string | null }>
  const p = productId ? products[productId] : null
  if (!p || p.period === 'consumable') return null
  const list = tierList()
  return p.access && list.indexOf(p.access) >= 0 ? p.access : list[0]
}

/**
 * Ouvre localement le niveau du produit ET les niveaux inférieurs (achat payé mais pas encore
 * vérifié, achat simulé de l'aperçu). Un niveau inférieur déjà actif est conservé tel quel.
 */
function grantProductTiers(all: Record<string, ZzzEntitlement>, productId: string, reason: string, expirationDate: string | null): void {
  const list = tierList()
  const tier = productTier(productId) || ZZZ_PAYWALL.entitlementId
  const top = list.indexOf(tier)
  const ids = top >= 0 ? list.slice(0, top + 1) : [tier]
  for (const id of ids) {
    if (id !== tier && all[id] && all[id].isActive) continue
    const level = list.indexOf(id)
    all[id] = { identifier: id, isActive: true, productIdentifier: productId, expirationDate: expirationDate, reason: reason, level: level >= 0 ? level : null, grantedBy: id === tier ? null : tier }
  }
}

/** Le niveau ouvert par ce produit est actif (un niveau supérieur l'ouvre aussi). */
function productAccessActive(info: CustomerInfo, productId: string | null | undefined): boolean {
  return hasAccess(info, productTier(productId) || ZZZ_PAYWALL.entitlementId)
}

/**
 * Appel BloxksPay. etag (même null) = lecture conditionnelle : renvoie alors
 * { notModified, body, etag } (304 → notModified, sans corps).
 */
async function api(path: string, init: { method: 'GET' | 'POST'; body?: unknown; etag?: string | null; timeoutMs?: number }): Promise<any> {
  if (!API_KEY) throw new Error('Bloxks Pay key missing')
  const controller = typeof AbortController !== 'undefined' ? new AbortController() : null
  const timer = controller ? setTimeout(() => controller.abort(), init.timeoutMs || 15000) : null
  const conditional = init.etag !== undefined
  try {
    const headers: Record<string, string> = { 'Content-Type': 'application/json', 'X-Bloxks-Pay-Key': API_KEY }
    if (init.etag) headers['If-None-Match'] = init.etag
    const res = await fetch(API_BASE + path, {
      method: init.method,
      headers: headers,
      body: init.body === undefined ? undefined : JSON.stringify(init.body),
      signal: controller ? controller.signal : undefined,
    })
    if (conditional && res.status === 304) return { notModified: true, body: null, etag: init.etag || null }
    const body = await res.json().catch(() => null)
    if (!res.ok) {
      const err = new Error((body && body.message) || 'Bloxks Pay ' + res.status) as Error & { status?: number; code?: string }
      err.status = res.status
      err.code = body && body.code
      throw err
    }
    // 200 illisible (portail captif, proxy) : pas une réponse de BloxksPay → panne, jamais un succès.
    if (!body || typeof body !== 'object') throw new Error('Bloxks Pay invalid response')
    if (conditional) return { notModified: false, body: body, etag: (res.headers && typeof res.headers.get === 'function' && res.headers.get('ETag')) || null }
    return body
  } finally {
    if (timer) clearTimeout(timer)
  }
}

// ---------------------------------------------------------- catalogue -----

type CatalogEntry = { productId: string; period: Period; price: string; currency: string; trialDuration: string }

function catalog(): CatalogEntry[] {
  const products = ZZZ_PAYWALL.products as Record<string, { price: string; currency: string; period: Period; trialDuration: string }>
  return Object.keys(products).map((id) => ({ productId: id, period: products[id].period, price: products[id].price, currency: products[id].currency, trialDuration: products[id].trialDuration }))
}

function catalogKey(ref: ProductRef): string | null {
  const products = ZZZ_PAYWALL.products as Record<string, unknown>
  const id = typeof ref === 'string' ? ref : ref.product.identifier
  return products[id] ? id : null
}

/**
 * Identifiant du produit chez le store. Google Play : même assainissement que la création
 * du catalogue Play (minuscules, chiffres, _ et .), sinon le produit est introuvable.
 */
function storeSku(productId: string): string {
  if (!IS_ANDROID) return productId
  const cleaned = productId.trim().toLowerCase().replace(/[^a-z0-9_.]/g, '_').replace(/^[^a-z0-9]+/, '').slice(0, 40)
  return cleaned || 'product'
}

/** Produit du catalogue d'après l'identifiant renvoyé par le store (identique sur iPhone). */
function catalogIdOf(storeId: string): string {
  if (!IS_ANDROID || !storeId) return storeId
  const products = ZZZ_PAYWALL.products as Record<string, unknown>
  if (products[storeId]) return storeId
  for (const key of Object.keys(products)) if (storeSku(key) === storeId) return key
  return storeId
}

/** Phase de prix récurrente d'une offre Google Play (après un éventuel essai). */
function recurringPhase(offer: any): any | null {
  const phases: any[] = (offer && offer.pricingPhasesAndroid && offer.pricingPhasesAndroid.pricingPhaseList) || []
  return phases.find((ph) => ph && ph.recurrenceMode === 1) || phases[phases.length - 1] || null
}

/**
 * Google Play : offre d'abonnement à acheter. Base plan de la cadence du catalogue (le nôtre,
 * sinon celui de même durée créé à la main dans la Play Console) ; l'essai gratuit quand le
 * catalogue en prévoit un et que Google y donne droit (il ne renvoie que les offres permises).
 */
function androidOffer(entry: CatalogEntry, product: any): any | null {
  const offers: any[] = (product && Array.isArray(product.subscriptionOffers) ? product.subscriptionOffers : []).filter((o: any) => o && o.offerTokenAndroid)
  let plan = offers.filter((o) => o.basePlanIdAndroid === PLAY_BASE_PLAN[entry.period])
  if (plan.length === 0) {
    plan = offers.filter((o) => {
      const phase = recurringPhase(o)
      return !!phase && phase.billingPeriod === PERIOD_ISO[entry.period]
    })
  }
  if (plan.length === 0) return null
  const trial = entry.trialDuration !== 'none' ? plan.find((o) => o.id === PLAY_TRIAL_OFFER) : null
  return trial || plan.find((o) => o.id === o.basePlanIdAndroid) || plan[0]
}

/** Google Play : prix d'un abonnement lu sur SON base plan (le produit peut en porter plusieurs). */
function androidPriced(product: any, offer: any): any {
  const phase = recurringPhase(offer)
  if (!phase) return product
  const micros = Number(phase.priceAmountMicros)
  return { ...product, price: isFinite(micros) ? micros / 1000000 : product.price, displayPrice: phase.formattedPrice || product.displayPrice, currency: phase.priceCurrencyCode || product.currency }
}

function formatPrice(amount: number, currency: string): string {
  try {
    return new Intl.NumberFormat(undefined, { style: 'currency', currency: currency }).format(amount)
  } catch {
    return amount.toFixed(2) + ' ' + currency
  }
}

function packageFor(entry: CatalogEntry, storeProduct: any | null, used: Set<string>): ZzzPackage {
  const standard = PACKAGE_ID[entry.period]
  const identifier = standard && !used.has(standard) ? standard : 'zzz_' + entry.productId.toLowerCase().replace(/[^a-z0-9_]/g, '_')
  used.add(identifier)
  const fallbackAmount = Number(String(entry.price).replace(',', '.')) || 0
  const amount = storeProduct && typeof storeProduct.price === 'number' ? storeProduct.price : fallbackAmount
  const currency = (storeProduct && storeProduct.currency) || entry.currency
  const isSub = !!PERIOD_ISO[entry.period]
  return {
    identifier: identifier,
    packageType: PACKAGE_TYPE[entry.period] || 'CUSTOM',
    offeringIdentifier: ZZZ_PAYWALL.offeringId || 'default',
    product: {
      identifier: entry.productId,
      title: (storeProduct && (storeProduct.displayName || storeProduct.title)) || entry.productId,
      description: (storeProduct && storeProduct.description) || '',
      price: amount,
      priceString: (storeProduct && storeProduct.displayPrice) || formatPrice(amount, currency),
      currencyCode: currency,
      subscriptionPeriod: isSub ? PERIOD_ISO[entry.period] : null,
      introPrice: null,
      productCategory: isSub ? 'SUBSCRIPTION' : 'NON_SUBSCRIPTION',
    },
  }
}

/** expo-iap chargé à la demande : le module natif n'existe ni dans Expo Go ni sur le web. */
function loadIap(): any {
  if (iap) return iap
  if (IS_WEB || IS_EXPO_GO || (Platform.OS !== 'ios' && !IS_ANDROID)) return null
  try {
    iap = require('expo-iap')
  } catch {
    iap = null
  }
  return iap
}

async function ensureConnection(): Promise<any> {
  const mod = loadIap()
  if (!mod) return null
  // Écouteurs AVANT initConnection : les transactions non terminées et les accords
  // « Demander à un parent » sont émis dès la connexion, et perdus sans écouteur.
  // Sans dédoublonnage : Apple re-livre la MÊME transaction quand on change d'abonnement,
  // et la vérification BloxksPay est idempotente.
  if (!listenersAttached) {
    listenersAttached = true
    mod.purchaseUpdatedListener((purchase: any) => {
      void handlePurchase(purchase)
    }, { dedupeTransactionIOS: false })
    mod.purchaseErrorListener((error: any) => {
      if (!pending) return
      // Erreur d'une AUTRE transaction (rejouée au lancement) : l'achat en cours continue.
      if (error && error.productId && !settlesPending(pending.sku, catalogIdOf(error.productId))) return
      const code = String((error && error.code) || '')
      const cancelled = typeof mod.isUserCancelledError === 'function' ? mod.isUserCancelledError(error) : false
      // Demander à un parent / validation bancaire : demande envoyée, pas un échec.
      if (code === 'deferred-payment' || code === 'pending') {
        settlePending({ success: false, entitlementActive: false, cancelled: false, error: 'pending' }, 'deferred')
        return
      }
      // Déjà acheté chez Apple : on relit les achats, le droit est très probablement actif.
      if (code === 'already-owned' && !isConsumable(pending.sku)) {
        void settleFromRestore(pending, 'already_owned', 'already_owned')
        return
      }
      // Android : pack payé mais jamais consommé (app fermée pendant l'achat) → Google refuse
      // le rachat. On le relit : vérifié, consommé et crédité via onConsumableDelivered.
      const replay = IS_ANDROID && code === 'already-owned'
      settlePending({ success: false, entitlementActive: false, cancelled: cancelled, error: cancelled ? undefined : code || 'purchase_failed' }, cancelled ? 'cancelled' : 'error:' + (code || 'purchase_failed'))
      if (replay) void replayAndroid(mod)
    })
  }
  if (!connected) {
    await mod.initConnection()
    connected = true
    if (IS_ANDROID) void replayAndroid(mod)
  }
  return mod
}

/**
 * Android : Google Play ne relivre PAS les achats inachevés au lancement (StoreKit, si). On
 * les relit : pièces non consommées et achats non acquittés (app fermée pendant l'achat,
 * panne de BloxksPay, achat en attente devenu payé) sont vérifiés puis terminés comme un
 * achat livré. Sans ça, Google rembourse d'office un achat non acquitté sous 3 jours.
 */
async function replayAndroid(mod: any): Promise<void> {
  try {
    const purchases: any[] = (await mod.getAvailablePurchases()) || []
    for (const p of purchases) {
      if (!p || !p.purchaseToken || p.purchaseState === 'pending') continue
      if (isConsumable(catalogIdOf(p.productId)) || p.isAcknowledgedAndroid === false) void handlePurchase(p)
    }
  } catch {
    /* relu au prochain retour dans l'app */
  }
}

/** Corps Google d'une vérification BloxksPay : identifiant Play, jeton, type de produit. */
function googleItem(p: any): { productId: string; purchaseToken: string; type: 'subs' | 'in-app' } {
  return { productId: String(p.productId), purchaseToken: String(p.purchaseToken), type: isSubscription(catalogIdOf(p.productId)) ? 'subs' : 'in-app' }
}

function isConsumable(productId: string): boolean {
  const products = ZZZ_PAYWALL.products as Record<string, { period: Period }>
  return products[productId] ? products[productId].period === 'consumable' : false
}

function isSubscription(productId: string): boolean {
  const products = ZZZ_PAYWALL.products as Record<string, { period: Period }>
  return products[productId] ? !!PERIOD_ISO[products[productId].period] : false
}

/**
 * Livraison attendue par l'achat en cours. Changer d'abonnement (mensuel → annuel)
 * pendant qu'un autre est actif : Apple programme le changement au renouvellement et
 * re-livre l'abonnement EN COURS. Sans ça, l'écran attendait le délai de 5 min.
 */
function settlesPending(requested: string, delivered: string): boolean {
  // Android : Google livre toujours le produit acheté (le remplacement d'abonnement est immédiat).
  return requested === delivered || (!IS_ANDROID && isSubscription(requested) && isSubscription(delivered))
}

/** Reçu Apple / jeton Google → vérification BloxksPay → fin de transaction. Appelé pour chaque achat livré par le store. */
async function handlePurchase(purchase: any): Promise<void> {
  const mod = loadIap()
  const jws = purchase && purchase.purchaseToken
  const storeId = purchase && purchase.productId
  const productId = IS_ANDROID ? catalogIdOf(storeId) : storeId
  // En attente (demander à un parent, validation bancaire) : rien n'est payé, aucun accès.
  // Apple re-livrera la transaction une fois acceptée.
  if (purchase && purchase.purchaseState === 'pending') {
    if (pending && productId && settlesPending(pending.sku, productId)) settlePending({ success: false, entitlementActive: false, cancelled: false, error: 'pending' }, 'deferred')
    return
  }
  const transactionIdentifier = purchase && (purchase.transactionId || purchase.id)
  const key = String(transactionIdentifier || productId || '')
  if (verifying.has(key)) return
  verifying.set(key, String(productId || ''))
  diag('purchase_delivered', { productId: productId || null, hasJws: !!jws, settles: !!(pending && productId && settlesPending(pending.sku, productId)) })
  let verified = false
  let entitlementActive = false
  let transient = false
  let expiresAt: string | null = null
  let local = false
  const userId = await currentUserId()
  try {
    if (!jws) {
      local = true
      throw new Error('missing JWS')
    }
    if (!API_KEY) local = true
    const body = await api('/v1/sdk/transactions', { method: 'POST', body: IS_ANDROID ? { appUserId: userId, google: [googleItem(purchase)] } : { appUserId: userId, transactions: [jws] } })
    const entitlements = entitlementsFromServer(body)
    await saveCache(userId, entitlements)
    const info = infoFrom(entitlements, userId)
    publish(info)
    entitlementActive = productAccessActive(info, productId)
    const entitlement = info.entitlements.all[productTier(productId) || ZZZ_PAYWALL.entitlementId]
    expiresAt = entitlement ? entitlement.expirationDate : null
    verified = true
    unverified.delete(key)
  } catch (e) {
    // Serveur injoignable, en panne, lent, saturé (429) ou réponse illisible : Apple a encaissé,
    // on ouvre l'accès localement (24 h) et la transaction reste NON terminée : StoreKit la
    // re-livrera au prochain lancement, et on la rejoue nous-mêmes dès la prochaine lecture des
    // droits. Jamais pour une erreur locale (reçu absent, clé manquante) ni un refus (4xx).
    const status = (e as { status?: number }).status
    transient = !local && (!status || status >= 500 || status === 429)
    if (transient) {
      unverified.set(key, purchase)
      if (productId && !isConsumable(productId)) {
        const prev = (await cachedInfo(userId)) || infoFrom({}, userId)
        const all = { ...prev.entitlements.all }
        grantProductTiers(all, productId, 'pending_verification', new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString())
        const info = infoFrom(all, userId)
        publish(info)
        entitlementActive = true
      }
    }
    console.warn('[Bloxks Pay] verification failed:', e instanceof Error ? e.message : String(e))
    diag('purchase_verify_failed', { productId: productId || null, status: status || null, local: local, transient: transient })
  }
  verifying.delete(key)
  // L'écran est libéré dès la vérification : la fin de transaction StoreKit vient après,
  // jamais entre les deux (un appel natif muet laissait la roue tourner).
  const settled = !!(pending && productId && settlesPending(pending.sku, productId))
  if (settled) {
    // Autre abonnement livré que celui demandé : Apple a programmé le changement, sans paiement.
    const scheduled = pending!.sku !== productId
    settlePending({
      success: verified || entitlementActive,
      entitlementActive: entitlementActive,
      cancelled: false,
      productIdentifier: productId,
      transactionIdentifier: scheduled ? undefined : transactionIdentifier,
      error: verified || entitlementActive ? undefined : transient ? 'pending_verification' : 'verification_failed',
      scheduledChange: scheduled ? { productIdentifier: pending!.sku, date: expiresAt } : undefined,
    }, verified ? (scheduled ? 'scheduled' : 'verified') : entitlementActive ? 'pending_verification' : 'unverified')
  }
  if (verified && mod) {
    try {
      if (!IS_ANDROID) await mod.finishTransaction({ purchase: purchase, isConsumable: isConsumable(productId) })
      // Android : pièces consommées (rachetables) ; abonnement et accès à vie déjà acquittés
      // par BloxksPay, acquittés ici seulement si Google les dit encore non acquittés.
      else if (isConsumable(productId)) await mod.finishTransaction({ purchase: purchase, isConsumable: true })
      else if (purchase.isAcknowledgedAndroid === false) await mod.finishTransaction({ purchase: purchase, isConsumable: false })
    } catch {
      /* re-livrée au prochain lancement (relue sur Android), la vérification est idempotente ; « déjà acquitté » : rien à faire */
    }
  }
  if (settled) return
  // Pack livré sans achat en attente (app fermée pendant l'achat, délai dépassé, réseau
  // revenu, transaction rejouée au lancement) : payé chez Apple, à créditer quand même.
  if (verified && productId && isConsumable(productId) && transactionIdentifier) reportConsumable(productId, String(transactionIdentifier))
}

/** Prévient les abonnés d'onConsumableDelivered, une seule fois par transaction. */
function reportConsumable(productIdentifier: string, transactionIdentifier: string): void {
  if (consumablesReported.has(transactionIdentifier)) return
  consumablesReported.add(transactionIdentifier)
  consumableListeners.forEach((cb) => {
    try {
      cb({ productIdentifier: productIdentifier, transactionIdentifier: transactionIdentifier })
    } catch {
      /* un abonné défaillant ne bloque pas les autres */
    }
  })
}

// ------------------------------------------------- simulation (aperçu web) -----

function simulatedPurchase(entry: CatalogEntry, userId: string): ZzzPurchaseResult {
  const transactionIdentifier = 'sim_' + Date.now()
  if (entry.period !== 'consumable') {
    const all: Record<string, ZzzEntitlement> = current && current.originalAppUserId === userId ? { ...current.entitlements.all } : {}
    grantProductTiers(all, entry.productId, 'simulated', null)
    // Web preview purchases are ephemeral: memory only, gone on reload.
    publish(infoFrom(all, userId))
  }
  return { success: true, entitlementActive: entry.period !== 'consumable', cancelled: false, productIdentifier: entry.productId, transactionIdentifier: transactionIdentifier }
}

// ------------------------------------------------------- API publique -----

/** Prépare la connexion au store (sans effet sur le web et dans Expo Go). Nom conservé pour le code existant. */
export function configureRevenueCat(): void {
  void ensureConnection().catch(() => {})
}

export const configureBilling = configureRevenueCat

// Connexion dès le chargement (iPhone, Android) : les achats laissés en suspens (app fermée
// pendant un paiement) sont vérifiés et terminés au lancement, sans attendre le paywall.
if (!IS_WEB && !IS_EXPO_GO && (Platform.OS === 'ios' || IS_ANDROID)) configureRevenueCat()

/**
 * Pack (pièces…) payé mais livré HORS de purchasePackage : app fermée pendant l'achat,
 * délai dépassé, réseau revenu plus tard. Le crédit se fait ici, une fois par
 * transactionIdentifier, comme pour le résultat de purchasePackage. Renvoie le désabonnement.
 */
export function onConsumableDelivered(cb: (delivery: { productIdentifier: string; transactionIdentifier: string }) => void): () => void {
  consumableListeners.add(cb)
  return () => {
    consumableListeners.delete(cb)
  }
}

/**
 * Pack acheté dans un écran qui ne crédite pas lui-même (paywall distant zzz/BloxksPaywall) :
 * signalé à onConsumableDelivered comme un pack livré hors achat. Une fois par transaction.
 */
export function deliverConsumable(result: ZzzPurchaseResult): void {
  const id = result && result.productIdentifier
  if (!result || !result.success || !id || !isConsumable(id) || !result.transactionIdentifier) return
  reportConsumable(id, result.transactionIdentifier)
}

export function getLastOfferingsError(): ZzzOfferingsError | null {
  return lastOfferingsError
}

/**
 * Offre du paywall : produits du catalogue, prix réels du store sur iPhone et Android,
 * prix de repli ailleurs. offeringId est accepté pour compatibilité (une seule offre).
 */
export async function fetchOffering(_offeringId?: string): Promise<ZzzOffering | null> {
  const entries = catalog()
  if (entries.length === 0) {
    lastOfferingsError = { code: 'NO_OFFERING', message: 'No product configured' }
    return null
  }
  // Produits chargés une fois par session : rouvrir le paywall ne repasse pas par Apple.
  let storeProducts: any[] = storeProductsCache || []
  try {
    const mod = storeProductsCache ? null : await ensureConnection()
    if (mod) {
      storeProducts = (await mod.fetchProducts({ skus: entries.map((e) => storeSku(e.productId)), type: 'all' })) || []
      if (storeProducts.length > 0) storeProductsCache = storeProducts
    }
  } catch (e) {
    lastOfferingsError = { code: 'STORE_ERROR', message: e instanceof Error ? e.message : String(e) }
    console.warn('[Bloxks Pay] fetchProducts failed:', lastOfferingsError.message)
  }
  const byId: Record<string, any> = {}
  for (const p of storeProducts) if (p && p.id) byId[catalogIdOf(p.id)] = p
  // Android : un abonnement sans base plan de sa cadence n'est pas achetable ; prix lu sur ce base plan.
  if (IS_ANDROID) {
    for (const e of entries) {
      if (!byId[e.productId] || !PERIOD_ISO[e.period]) continue
      const offer = androidOffer(e, byId[e.productId])
      if (offer) byId[e.productId] = androidPriced(byId[e.productId], offer)
      else delete byId[e.productId]
      // Google ne renvoie que les offres permises : sans l'offre d'essai, ce client n'y a pas droit.
      if (offer && e.trialDuration !== 'none' && offer.id !== PLAY_TRIAL_OFFER) trialRefusedByStore.add(e.productId)
      else trialRefusedByStore.delete(e.productId)
    }
  }
  const native = !!loadIap()
  // Sur iPhone et Android, un produit que le store ne connaît pas n'est pas achetable : on ne l'affiche pas.
  const usable = native ? entries.filter((e) => !!byId[e.productId]) : entries
  if (native && usable.length === 0) {
    lastOfferingsError = lastOfferingsError || { code: 'CONFIGURATION_ERROR', message: IS_ANDROID ? 'No product returned by Google Play' : 'No product returned by the App Store' }
  } else if (usable.length > 0) {
    lastOfferingsError = null
  }
  const used = new Set<string>()
  const packages = usable.map((e) => packageFor(e, byId[e.productId] || null, used))
  const find = (type: string) => packages.find((p) => p.packageType === type) || null
  return {
    identifier: ZZZ_PAYWALL.offeringId || 'default',
    availablePackages: packages,
    weekly: find('WEEKLY'),
    monthly: find('MONTHLY'),
    twoMonth: find('TWO_MONTH'),
    threeMonth: find('THREE_MONTH'),
    sixMonth: find('SIX_MONTH'),
    annual: find('ANNUAL'),
    lifetime: find('LIFETIME'),
  }
}

export async function fetchPackages(offeringId?: string): Promise<ZzzPackage[]> {
  const offering = await fetchOffering(offeringId)
  return offering ? offering.availablePackages : []
}

export function productContext(ref: ProductRef) {
  const key = catalogKey(ref)
  return key ? (ZZZ_PAYWALL.products as Record<string, { price: string; currency: string; period: Period; trialDuration: string }>)[key] : null
}

export function productPeriod(ref: ProductRef): string | null {
  const ctx = productContext(ref)
  return ctx ? ctx.period : null
}

/** Essai gratuit du produit ('none' sans essai, ou quand Google Play ne le propose pas à ce client). */
export function productTrialDuration(ref: ProductRef): string {
  const key = catalogKey(ref)
  const ctx = productContext(ref)
  if (!ctx || (key && trialRefusedByStore.has(key))) return 'none'
  return ctx.trialDuration
}

export function productHasFreeTrial(ref: ProductRef): boolean {
  return productTrialDuration(ref) !== 'none'
}

export function fallbackPrice(ref: ProductRef): string | null {
  const ctx = productContext(ref)
  if (!ctx || !ctx.price) return null
  return ctx.price + ' ' + ctx.currency
}

/**
 * Accès ouvert ? Avec un niveau ('premium'…) : ce niveau ou un niveau supérieur (= hasAccess).
 * Sans niveau : au moins un accès payé, c'est-à-dire le niveau le plus bas (tout niveau détenu l'ouvre).
 */
export function isEntitlementActive(customerInfo: { entitlements: { active: Record<string, unknown> } }, access?: string): boolean {
  return hasAccess(customerInfo, access || tierList()[0])
}

/**
 * Le client a accès au niveau tier : il le détient, ou détient un niveau supérieur
 * (Premium ouvre Pro). Un identifiant hors échelle est lu tel quel.
 */
export function hasAccess(info: { entitlements: { active: Record<string, unknown> } }, tier: string): boolean {
  const list = tierList()
  const level = list.indexOf(tier)
  if (level < 0) return !!info.entitlements.active[tier]
  for (let i = level; i < list.length; i++) if (info.entitlements.active[list[i]]) return true
  return false
}

/** Niveau le plus HAUT actif (null = aucun accès). */
export function currentTier(info: { entitlements: { active: Record<string, unknown> } }): string | null {
  const list = tierList()
  for (let i = list.length - 1; i >= 0; i--) if (info.entitlements.active[list[i]]) return list[i]
  return null
}

/**
 * Achète un package. Ne lève jamais : distingue l'annulation (aucun message à
 * afficher) d'un échec réel. Sur le web (aperçu), l'achat est simulé.
 */
export async function purchasePackage(pkg: ZzzPackage): Promise<ZzzPurchaseResult> {
  const sku = pkg && pkg.product ? pkg.product.identifier : ''
  const entry = catalog().find((e) => e.productId === sku)
  if (!entry) return { success: false, entitlementActive: false, cancelled: false, error: 'unknown_product' }
  // Verrou posé AVANT toute attente : deux appuis rapides sur « S'abonner » n'ouvrent qu'une feuille Apple.
  if (pending || purchaseStarting) return { success: false, entitlementActive: false, cancelled: false, error: 'purchase_in_progress' }
  purchaseStarting = true
  try {
    return await startPurchase(entry, sku)
  } finally {
    purchaseStarting = false
  }
}

async function startPurchase(entry: CatalogEntry, sku: string): Promise<ZzzPurchaseResult> {
  const userId = await currentUserId()
  if (IS_WEB) return simulatedPurchase(entry, userId)
  if (IS_EXPO_GO) return { success: false, entitlementActive: false, cancelled: false, error: 'store_build_required' }
  if (Platform.OS !== 'ios' && !IS_ANDROID) return { success: false, entitlementActive: false, cancelled: false, error: 'unsupported_platform' }
  const isSub = !!PERIOD_ISO[entry.period]
  // Accès à vie déjà acquis à ce niveau ou au-dessus : l'achat n'ouvrirait rien de plus et
  // serait facturé pour rien. Un niveau supérieur reste achetable (à vie Pro → Premium), et un
  // ABONNEMENT détenu ne bloque jamais : Apple gère le changement d'offre dans le groupe.
  const target = productTier(sku)
  if (target) {
    const known = current || (await cachedInfo(userId))
    const list = tierList()
    const from = Math.max(0, list.indexOf(target))
    for (let i = from; known && i < list.length; i++) {
      const owned = known.entitlements.active[list[i]]
      if (owned && owned.reason === 'lifetime') return { success: false, entitlementActive: true, cancelled: false, productIdentifier: owned.productIdentifier || undefined, error: 'already_owned_lifetime' }
    }
  }
  try {
    const mod = await ensureConnection()
    if (!mod) return { success: false, entitlementActive: false, cancelled: false, error: 'store_unavailable' }
    const token = await currentAccountToken()
    const request = isSub
      ? { request: { apple: { sku: sku, appAccountToken: token } }, type: 'subs' }
      : { request: { apple: { sku: sku, appAccountToken: token, quantity: 1 } }, type: 'in-app' }
    if (IS_ANDROID) {
      const google = await androidRequest(mod, entry, token)
      if (!google) return { success: false, entitlementActive: false, cancelled: false, error: 'store_unavailable' }
      request.request = { google: google } as any
    }
    watchAppState()
    const result = new Promise<ZzzPurchaseResult>((resolve) => {
      // Android met les minuteries en pause sous la feuille Google : au retour, ce délai expire en
      // même temps que la livraison de l'achat payé (ticket 894b3412). Une vérification en vol
      // conclut seule ; sinon on relit les achats avant de déclarer l'échec.
      const timer = setTimeout(() => {
        const p = pending
        if (!p || p.sku !== sku || verifyingPending(p)) return
        void settleFromRestore(p, 'timeout', 'timeout')
      }, PURCHASE_TIMEOUT_MS)
      pending = { sku: sku, resolve: resolve, timer: timer, net: null, startedAt: Date.now() }
    })
    diag('purchase_started', { sku: sku, type: isSub ? 'subs' : 'in-app' })
    await mod.requestPurchase(request)
    return await result
  } catch (e) {
    const mod = loadIap()
    const cancelled = mod && typeof mod.isUserCancelledError === 'function' ? mod.isUserCancelledError(e) : false
    const result: ZzzPurchaseResult = { success: false, entitlementActive: false, cancelled: cancelled, error: cancelled ? undefined : 'purchase_failed' }
    if (pending && pending.sku === sku) settlePending(result, cancelled ? 'cancelled' : 'request_failed')
    return result
  }
}

/**
 * Requête d'achat Google Play. Abonnement : offre (offerToken) du base plan de sa cadence ;
 * un abonnement actif d'un AUTRE produit du même accès est remplacé (purchaseToken), sinon
 * Google en ouvre un second et le client paie les deux. null = produit absent de Google Play.
 */
async function androidRequest(mod: any, entry: CatalogEntry, token: string): Promise<any | null> {
  const sku = storeSku(entry.productId)
  if (!PERIOD_ISO[entry.period]) return { skus: [sku], obfuscatedAccountId: token }
  let product = (storeProductsCache || []).find((p: any) => p && p.id === sku)
  if (!product) product = ((await mod.fetchProducts({ skus: [sku], type: 'subs' })) || []).find((p: any) => p && p.id === sku)
  const offer = androidOffer(entry, product)
  if (!offer) return null
  const google: any = { skus: [sku], subscriptionOffers: [{ sku: sku, offerToken: offer.offerTokenAndroid }], obfuscatedAccountId: token }
  try {
    const owned: any[] = (await mod.getAvailablePurchases()) || []
    const old = owned.find((p) => {
      const id = p && p.purchaseToken && p.purchaseState !== 'pending' ? catalogIdOf(p.productId) : ''
      return !!id && id !== entry.productId && isSubscription(id) && productTier(id) === productTier(entry.productId)
    })
    if (old) google.purchaseToken = old.purchaseToken
  } catch {
    /* achats illisibles : achat simple */
  }
  return google
}

async function sendRestore(): Promise<CustomerInfo | null> {
  const mod = await ensureConnection()
  const userId = await currentUserId()
  if (!mod) return null
  const purchases = (await mod.getAvailablePurchases()) || []
  if (IS_ANDROID) {
    // Achats payés des produits du catalogue (un achat en attente n'ouvre rien).
    const products = ZZZ_PAYWALL.products as Record<string, unknown>
    const google = purchases.filter((p: any) => p && typeof p.purchaseToken === 'string' && p.purchaseToken.length > 0 && p.purchaseState !== 'pending' && !!products[catalogIdOf(p.productId)]).slice(0, 50).map(googleItem)
    if (google.length === 0) return getCustomerInfo()
    const restored = await api('/v1/sdk/restore', { method: 'POST', body: { appUserId: userId, google: google } })
    const fromGoogle = entitlementsFromServer(restored)
    await saveCache(userId, fromGoogle)
    const androidInfo = infoFrom(fromGoogle, userId)
    publish(androidInfo)
    return androidInfo
  }
  const tokens = purchases.map((p: any) => p && p.purchaseToken).filter((t: unknown) => typeof t === 'string' && t.length > 0).slice(0, 50)
  if (tokens.length === 0) return getCustomerInfo()
  const body = await api('/v1/sdk/restore', { method: 'POST', body: { appUserId: userId, transactions: tokens } })
  const entitlements = entitlementsFromServer(body)
  await saveCache(userId, entitlements)
  const info = infoFrom(entitlements, userId)
  publish(info)
  return info
}

/**
 * Bouton « J'ai un code » : ouvre la fenêtre OFFICIELLE d'Apple pour saisir un code
 * promo (Apple interdit une saisie maison). Le code utilisé arrive comme un achat :
 * il est vérifié par BloxksPay puis l'accès est relu. Android : la page « Utiliser un
 * code » du Play Store s'ouvre hors de l'app ; l'accès est relu au retour dans l'app.
 * Indisponible dans l'aperçu web et Expo Go (store_build_required) : le bouton n'agit
 * que dans l'app installée.
 */
export async function redeemOfferCode(): Promise<ZzzPurchaseResult> {
  if (IS_WEB || IS_EXPO_GO) return { success: false, entitlementActive: false, cancelled: false, error: 'store_build_required' }
  if (Platform.OS !== 'ios' && !IS_ANDROID) return { success: false, entitlementActive: false, cancelled: false, error: 'unsupported_platform' }
  try {
    const mod = await ensureConnection()
    if (!mod || typeof mod.openRedeemOfferCode !== 'function') return { success: false, entitlementActive: false, cancelled: false, error: 'store_unavailable' }
    // État AVANT la fenêtre (mémoire, sinon cache local) : déjà abonné + fenêtre fermée ≠ code utilisé.
    const known = current || (await cachedInfo(await currentUserId()))
    const before = known ? currentTier(known) : null
    const purchase = await mod.openRedeemOfferCode()
    if (IS_ANDROID) await untilForeground(STORE_RETURN_MS)
    // Apple ne renvoie le code utilisé que rarement (null même après un succès) : on relit
    // toujours les achats, et seule une fenêtre fermée SANS changement de niveau compte comme annulée.
    const info = await sendRestore()
    const active = info ? isEntitlementActive(info) : false
    if (!purchase && (!active || (info ? currentTier(info) : null) === before)) return { success: false, entitlementActive: active, cancelled: true }
    return { success: true, entitlementActive: active, cancelled: false, productIdentifier: purchase ? purchase.productId : undefined }
  } catch {
    return { success: false, entitlementActive: false, cancelled: false, error: 'redeem_failed' }
  }
}

/**
 * Bouton « Demander un remboursement » : ouvre la fenêtre OFFICIELLE d'Apple pour le
 * dernier achat du produit (par défaut, celui qui ouvre l'accès). Apple décide ; s'il
 * rembourse, BloxksPay coupe l'accès, relu à la prochaine lecture des droits. En test
 * (TestFlight), Apple accepte tout seul ; motif « Autre » + « DECLINE » pour un refus.
 * Android : unsupported_platform. Google n'offre aucune demande de remboursement dans
 * l'app : le client passe par play.google.com (historique des commandes) ou le support de
 * l'app ; un remboursement accordé coupe l'accès, relu par BloxksPay.
 * Indisponible dans l'aperçu web et Expo Go (store_build_required).
 */
export async function requestRefund(productId?: string): Promise<ZzzRefundResult> {
  if (IS_WEB || IS_EXPO_GO) return { submitted: false, cancelled: false, error: 'store_build_required' }
  if (Platform.OS !== 'ios') return { submitted: false, cancelled: false, error: 'unsupported_platform' }
  try {
    const mod = await ensureConnection()
    if (!mod || typeof mod.beginRefundRequestIOS !== 'function') return { submitted: false, cancelled: false, error: 'store_unavailable' }
    let sku = productId || ''
    if (!sku) {
      const info = await getCustomerInfo()
      // Produit du niveau le plus haut détenu EN PROPRE (pas celui ouvert par un niveau supérieur).
      const list = tierList()
      for (let i = list.length - 1; info && !sku && i >= 0; i--) {
        const entitlement = info.entitlements.active[list[i]]
        if (entitlement && !entitlement.grantedBy && entitlement.productIdentifier) sku = entitlement.productIdentifier
      }
    }
    if (!sku) return { submitted: false, cancelled: false, error: 'nothing_to_refund' }
    const status = await mod.beginRefundRequestIOS(sku)
    if (status === 'success') return { submitted: true, cancelled: false }
    if (status === 'userCancelled') return { submitted: false, cancelled: true }
    return { submitted: false, cancelled: false, error: 'refund_failed' }
  } catch (e) {
    const mod = loadIap()
    const cancelled = mod && typeof mod.isUserCancelledError === 'function' ? mod.isUserCancelledError(e) : false
    return { submitted: false, cancelled: cancelled, error: cancelled ? undefined : 'refund_failed' }
  }
}

/**
 * Bouton « Gérer l'abonnement » : ouvre la fenêtre OFFICIELLE d'Apple DANS l'app
 * (changer d'offre, résilier). Contrairement au lien apps.apple.com/account/subscriptions,
 * elle montre aussi les abonnements TestFlight. Une résiliation garde l'accès jusqu'à
 * la fin de la période payée ; l'état est relu à la fermeture. Android : la page
 * « Abonnements » du Play Store s'ouvre hors de l'app (sur l'abonnement en cours quand il
 * est connu) ; l'état est relu au retour dans l'app.
 * Indisponible dans l'aperçu web et Expo Go (store_build_required).
 */
export async function manageSubscriptions(): Promise<ZzzPurchaseResult> {
  if (IS_WEB || IS_EXPO_GO) return { success: false, entitlementActive: false, cancelled: false, error: 'store_build_required' }
  if (Platform.OS !== 'ios' && !IS_ANDROID) return { success: false, entitlementActive: false, cancelled: false, error: 'unsupported_platform' }
  try {
    const mod = await ensureConnection()
    if (IS_ANDROID) {
      if (!mod || typeof mod.deepLinkToSubscriptions !== 'function') return { success: false, entitlementActive: false, cancelled: false, error: 'store_unavailable' }
      const known = current || (await cachedInfo(await currentUserId()))
      const active = known ? known.entitlements.active : {}
      const entitlement = active[ZZZ_PAYWALL.entitlementId] || active[Object.keys(active)[0]] || null
      const sku = entitlement && entitlement.productIdentifier && isSubscription(entitlement.productIdentifier) ? storeSku(entitlement.productIdentifier) : ''
      await mod.deepLinkToSubscriptions(sku ? { skuAndroid: sku } : {})
      await untilForeground(STORE_RETURN_MS)
    } else {
      if (!mod || typeof mod.showManageSubscriptionsIOS !== 'function') return { success: false, entitlementActive: false, cancelled: false, error: 'store_unavailable' }
      await mod.showManageSubscriptionsIOS()
    }
    const info = await sendRestore()
    // Apple confirme parfois la résiliation quelques secondes après la fermeture : seconde lecture.
    setTimeout(() => { getCustomerInfo().catch(() => {}) }, 8000)
    return { success: true, entitlementActive: info ? isEntitlementActive(info) : false, cancelled: false }
  } catch {
    return { success: false, entitlementActive: false, cancelled: false, error: 'manage_failed' }
  }
}

/** Restaure les achats (bouton « Restaurer » — OBLIGATOIRE pour la revue Apple). */
export async function restorePurchases(): Promise<ZzzPurchaseResult> {
  try {
    if (IS_WEB) {
      const info = await getCustomerInfo()
      return { success: true, entitlementActive: info ? isEntitlementActive(info) : false, cancelled: false }
    }
    const info = await sendRestore()
    return { success: !!info, entitlementActive: info ? isEntitlementActive(info) : false, cancelled: false }
  } catch {
    return { success: false, entitlementActive: false, cancelled: false, error: 'restore_failed' }
  }
}

/**
 * Rattache l'appareil à l'identité du joueur (typiquement l'auth.uid() Supabase).
 * Les achats déjà faits sur l'appareil suivent ce compte (resynchronisation silencieuse).
 */
export async function identifyPlayer(userId: string): Promise<void> {
  if (!userId) return
  const id = String(userId).slice(0, 128)
  if (appUserId === id) return
  appUserId = id
  await writeStore('user', id)
  // L'état et la lecture en vol appartiennent à l'ancienne identité : on repart de zéro.
  current = null
  infoInFlight = null
  void syncPurchasesSilently()
}

/** Resynchronisation SILENCIEUSE des reçus (démarrage, réinstallation) : aucune fenêtre store. */
export async function syncPurchasesSilently(): Promise<void> {
  try {
    if (IS_WEB) return
    await sendRestore()
  } catch {
    /* jamais bloquant */
  }
}

/**
 * État d'abonnement courant (serveur, sinon mémoire locale), ou null si inconnu.
 * Une seule lecture en vol : trois écrans qui s'ouvrent ensemble partagent la même requête
 * (on voyait 3 appels identiques dans la même seconde, chacun recalculant les droits).
 */
export async function getCustomerInfo(): Promise<CustomerInfo | null> {
  if (!infoInFlight) {
    infoInFlight = fetchCustomerInfo()
    infoInFlight.then(() => { infoInFlight = null }, () => { infoInFlight = null })
  }
  return infoInFlight
}

async function fetchCustomerInfo(): Promise<CustomerInfo | null> {
  const userId = await currentUserId()
  if (IS_WEB) return current || infoFrom({}, userId)
  // Achat encaissé mais jamais confirmé (panne) : on rejoue d'abord sa vérification. Tant qu'elle
  // échoue, l'accès ouvert localement reste la référence : une lecture serveur (qui n'a jamais
  // reçu le reçu) ou un vieux cache ne doivent pas le refermer.
  if (unverified.size > 0 && !pending) {
    await Promise.all(Array.from(unverified.values()).map((purchase) => handlePurchase(purchase)))
    if (unverified.size > 0) return current
  }
  try {
    const body = await api('/v1/sdk/customer?appUserId=' + encodeURIComponent(userId), { method: 'GET' })
    const entitlements = entitlementsFromServer(body)
    await saveCache(userId, entitlements)
    const info = infoFrom(entitlements, userId)
    publish(info)
    return info
  } catch (e) {
    // Clé révoquée ou app suspendue : réponse ferme de BloxksPay, pas une panne → droits fermés.
    const status = (e as { status?: number }).status
    if (status === 401 || status === 403) {
      const closed = infoFrom({}, userId)
      publish(closed)
      return closed
    }
    // Panne (réseau, 5xx, délai) : on garde ce qu'on sait (un droit déjà vérifié reste ouvert 7 jours).
    const cached = await cachedInfo(userId)
    if (cached && userId === appUserId) current = cached
    return cached || current
  }
}

export async function isEntitlementActiveNow(access?: string): Promise<boolean> {
  const info = await getCustomerInfo()
  return info ? isEntitlementActive(info, access) : false
}

/**
 * Comme onCustomerInfoUpdate, mais reçoit l'état COMPLET : pour un écran « Mon abonnement »
 * qui affiche la résiliation (willRenew === false → accès jusqu'à expirationDate) ou
 * l'offre suivante (renewalProductIdentifier).
 */
export function onCustomerInfoChange(cb: (info: CustomerInfo) => void): () => void {
  subscribers.add(cb)
  watchAppState()
  if (current) cb(current)
  return () => {
    subscribers.delete(cb)
  }
}

/**
 * S'abonne aux changements d'abonnement (achat, restauration, renouvellement,
 * remboursement, expiration). Les droits sont relus chez BloxksPay à chaque retour
 * dans l'app : un remboursement accordé par Apple coupe l'accès sans relancer l'app.
 * Renvoie une fonction de désabonnement à appeler au démontage.
 */
export function onCustomerInfoUpdate(cb: (isActive: boolean) => void, access?: string): () => void {
  const listener = (info: CustomerInfo) => cb(isEntitlementActive(info, access))
  subscribers.add(listener)
  watchAppState()
  if (current) listener(current)
  return () => {
    subscribers.delete(listener)
  }
}

// ---------------------------------------------------- paywalls distants -----
// Paywalls décrits en JSON et publiés depuis Bloxks Pay, dessinés par zzz/BloxksPaywall.
// Jamais bloquant, jamais d'exception : sans configuration lisible, l'app garde son paywall codé.

/** Version du moteur embarqué : égale à RENDERER_VERSION de zzz/paywallEngine (vérifié par un test). */
export const REMOTE_PAYWALL_RENDERER = 1
const PAYWALLS_TTL_MS = 5 * 60 * 1000
const PAYWALLS_TIMEOUT_MS = 4000
// Premier affichage sans configuration mémorisée : au plus 1,5 s d'attente, puis paywall codé.
const PAYWALLS_WAIT_MS = 1500
// Copie mémorisée : au plus 0,8 s pour vérifier qu'une nouvelle version n'a pas été publiée.
const PAYWALLS_REVALIDATE_WAIT_MS = 800
const EVENTS_FLUSH_MS = 2000
const EVENTS_BATCH = 50
// Hors ligne longtemps : la file des mesures reste bornée (les plus anciennes partent).
const EVENTS_MAX_QUEUE = 200
const PLACEMENT_RE = /^[a-z0-9_-]{1,40}$/

export type RemotePaywallResolution =
  | { kind: 'remote'; document: any; paywallId: string; paywallKey: string; revision: number; experimentId?: string; variantId?: string; trialEligible: boolean | null }
  | { kind: 'holdout'; experimentId: string; variantId: string }
  | { kind: 'none' }

export type PaywallEventKind = 'paywall_impression' | 'paywall_close' | 'package_selected' | 'purchase_started' | 'purchase_completed' | 'purchase_failed' | 'purchase_cancelled' | 'restore_completed' | 'holdout' | 'paywall_fallback'

// paywall_fallback : version publiée reçue que l'app ne sait pas dessiner (reason : invalid, schema,
// renderer, no_package) ; un paywall de secours est montré. Bloxks Pay remet alors la version précédente.
export type PaywallEvent = { kind: PaywallEventKind; placement?: string; paywallId?: string; revision?: number; experimentId?: string; variantId?: string; productId?: string; price?: number; currency?: string; reason?: string }

type RemoteConfig = { placements: Record<string, any>; paywalls: Record<string, any>; trialEligible: boolean | null }
type RemoteEntry = { userId: string; etag: string | null; fetchedAt: number; config: RemoteConfig }

let remoteEntry: RemoteEntry | null = null
let remoteInFlight: Promise<RemoteEntry | null> | null = null
let remoteTriedAt = 0
const paywallEvents: any[] = []
let eventsTimer: ReturnType<typeof setTimeout> | null = null
let eventsFlushing = false

/** Aperçu web, Expo Go ou clé absente : aucun appel, le paywall codé reste affiché. */
function remoteEnabled(): boolean {
  return !IS_WEB && !IS_EXPO_GO && !!API_KEY
}

/** Seau A/B (0 à 99) : FNV-1a 32 bits de experimentId + ':' + appUserId, identique côté serveur. */
export function experimentBucket(experimentId: string, userId: string): number {
  const s = String(experimentId) + ':' + String(userId)
  let h = 0x811c9dc5
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i)
    h = Math.imul(h, 0x01000193) >>> 0
  }
  return h % 100
}

/** Configuration mémorisée de ce client (mémoire, sinon stockage), même périmée. */
async function cachedPaywalls(userId: string): Promise<RemoteEntry | null> {
  if (remoteEntry && remoteEntry.userId === userId) return remoteEntry
  const raw = await readStore('paywalls:' + userId)
  if (!raw) return null
  try {
    const entry = JSON.parse(raw) as RemoteEntry
    if (!entry || !entry.config || typeof entry.config.placements !== 'object') return null
    remoteEntry = entry
    return entry
  } catch {
    return null
  }
}

/** Relit la configuration (ETag : 304 = inchangée). Panne → configuration mémorisée. */
function fetchPaywalls(userId: string): Promise<RemoteEntry | null> {
  if (remoteInFlight) return remoteInFlight
  remoteInFlight = (async () => {
    const prev = await cachedPaywalls(userId)
    remoteTriedAt = Date.now()
    try {
      const r = await api('/v1/sdk/paywalls?renderer=' + REMOTE_PAYWALL_RENDERER + '&appUserId=' + encodeURIComponent(userId), { method: 'GET', etag: prev ? prev.etag : null, timeoutMs: PAYWALLS_TIMEOUT_MS })
      let entry: RemoteEntry | null = null
      if (r.notModified) entry = prev ? { ...prev, fetchedAt: Date.now() } : null
      else if (r.body.placements && typeof r.body.placements === 'object') {
        const config: RemoteConfig = { placements: r.body.placements, paywalls: r.body.paywalls && typeof r.body.paywalls === 'object' ? r.body.paywalls : {}, trialEligible: typeof r.body.trialEligible === 'boolean' ? r.body.trialEligible : null }
        entry = { userId: userId, etag: r.etag, fetchedAt: Date.now(), config: config }
      }
      if (!entry) return prev
      remoteEntry = entry
      await writeStore('paywalls:' + userId, JSON.stringify(entry))
      return entry
    } catch {
      return prev
    }
  })()
  remoteInFlight.then(() => { remoteInFlight = null }, () => { remoteInFlight = null })
  return remoteInFlight
}

function within<T>(p: Promise<T>, ms: number, fallback: T): Promise<T> {
  return new Promise((resolve) => {
    const timer = setTimeout(() => resolve(fallback), ms)
    p.then((v) => { clearTimeout(timer); resolve(v) }, () => { clearTimeout(timer); resolve(fallback) })
  })
}

/**
 * Lit la configuration des paywalls distants si elle date de plus de 5 min (au lancement,
 * pour qu'elle soit prête à la première ouverture). Ne lève jamais.
 */
export async function refreshPaywalls(): Promise<void> {
  if (!remoteEnabled()) return
  try {
    const userId = await currentUserId()
    const cached = await cachedPaywalls(userId)
    if (!cached || Date.now() - Math.max(cached.fetchedAt, remoteTriedAt) > PAYWALLS_TTL_MS) await fetchPaywalls(userId)
  } catch {
    /* jamais bloquant */
  }
}

/** Variante du test A/B, mémorisée par test : changer les poids ne déplace pas un client déjà affecté. */
async function assignedVariant(experiment: any, userId: string): Promise<any | null> {
  const variants: any[] = Array.isArray(experiment.variants) ? experiment.variants : []
  const key = 'ab:' + experiment.id
  const saved = await readStore(key)
  const kept = saved ? variants.find((v) => v && v.id === saved) : null
  if (kept) return kept
  const bucket = experimentBucket(experiment.id, userId)
  let sum = 0
  for (const v of variants) {
    sum += Number(v && v.weight) || 0
    if (bucket < sum) {
      await writeStore(key, String(v.id))
      return v
    }
  }
  return null
}

/**
 * Paywall à montrer pour cet emplacement ('default' = usePaywall().open() sans argument ; clé
 * absente de la configuration = réglage de 'default') :
 * 'remote' (paywall publié), 'holdout' (groupe témoin : ne rien montrer) ou 'none' (garder
 * le paywall codé). Configuration relue à chaque ouverture : au plus 0,8 s d'attente avec une
 * copie mémorisée (sinon cette copie), 1,5 s sans. Ne lève jamais.
 */
export async function resolvePaywall(placement?: string): Promise<RemotePaywallResolution> {
  const none: RemotePaywallResolution = { kind: 'none' }
  if (!remoteEnabled()) return none
  try {
    const userId = await currentUserId()
    // Relue à CHAQUE ouverture (ETag : 304 sans corps si rien n'a changé), pour qu'une version
    // publiée dans Bloxks Pay apparaisse dès l'ouverture suivante. Réseau lent ou absent : copie
    // mémorisée, et la relecture finit en arrière-plan.
    const cached = await cachedPaywalls(userId)
    const entry = await within(fetchPaywalls(userId), cached ? PAYWALLS_REVALIDATE_WAIT_MS : PAYWALLS_WAIT_MS, cached)
    // Emplacement absent de Bloxks Pay (open('onboarding')), ou créé sans paywall ni test : il suit
    // 'default', test A/B compris ; les mesures gardent l'emplacement demandé.
    const placements = entry ? entry.config.placements : null
    const own = placements ? placements[placement || 'default'] : null
    const place = own && (own.paywall || (own.experiment && own.experiment.id)) ? own : placements ? placements['default'] || own : null
    if (!entry || !place) return none
    let paywallKey: string | null = place.paywall || null
    let experimentId: string | undefined
    let variantId: string | undefined
    const experiment = place.experiment
    if (experiment && experiment.id) {
      const variant = await assignedVariant(experiment, userId)
      if (variant) {
        experimentId = String(experiment.id)
        variantId = String(variant.id)
        if (!variant.paywall) return { kind: 'holdout', experimentId: experimentId, variantId: variantId }
        paywallKey = String(variant.paywall)
      }
    }
    const paywall = paywallKey ? entry.config.paywalls[paywallKey] : null
    if (!paywallKey || !paywall || !paywall.document || typeof paywall.document !== 'object') return none
    // Document que ce moteur ne sait pas dessiner (cache d'une version plus récente) : paywall codé,
    // et le repli est mesuré pour que Bloxks Pay remette la version précédente si besoin.
    if (paywall.document.schemaVersion !== 1 || !(Number(paywall.document.minRenderer) <= REMOTE_PAYWALL_RENDERER)) {
      trackPaywallEvent({ kind: 'paywall_fallback', reason: paywall.document.schemaVersion !== 1 ? 'schema' : 'renderer', placement: placement || 'default', paywallId: String(paywall.id), revision: Number(paywall.revision) || undefined, experimentId: experimentId, variantId: variantId })
      return none
    }
    return { kind: 'remote', document: paywall.document, paywallId: String(paywall.id), paywallKey: paywallKey, revision: Number(paywall.revision) || 0, experimentId: experimentId, variantId: variantId, trialEligible: entry.config.trialEligible }
  } catch {
    return none
  }
}

/** Envoie les événements en attente, par lots de 50 ; un seul nouvel essai après une panne, puis abandon silencieux. */
async function flushPaywallEvents(): Promise<void> {
  if (eventsTimer) clearTimeout(eventsTimer)
  eventsTimer = null
  if (eventsFlushing) return
  eventsFlushing = true
  try {
    while (paywallEvents.length > 0) {
      const batch = paywallEvents.splice(0, EVENTS_BATCH)
      const userId = await currentUserId()
      const send = () => api('/v1/sdk/paywall-events', { method: 'POST', body: { appUserId: userId, events: batch }, timeoutMs: PAYWALLS_TIMEOUT_MS })
      // Nouvel essai seulement après une panne (réseau, 5xx) : un refus (400) ou un 429 ne s'arrange pas en réessayant.
      await send().catch((e) => { const st = e && e.status; if (st && st < 500) return; return send() }).catch(() => {})
    }
  } finally {
    eventsFlushing = false
  }
}

/** Mesure d'un paywall distant (affichage, achat…) : envoyée par lots, jamais dans l'aperçu web. */
export function trackPaywallEvent(event: PaywallEvent): void {
  if (!remoteEnabled() || !event || !event.kind) return
  // Le serveur refuse tout le lot pour un seul emplacement mal formé (open('Mon écran')) : écarté ici.
  if (!PLACEMENT_RE.test(String(event.placement || ''))) return
  paywallEvents.push({ ...event, at: new Date().toISOString() })
  if (paywallEvents.length > EVENTS_MAX_QUEUE) paywallEvents.splice(0, paywallEvents.length - EVENTS_MAX_QUEUE)
  if (paywallEvents.length >= 10) void flushPaywallEvents()
  else if (!eventsTimer) eventsTimer = setTimeout(() => { void flushPaywallEvents() }, EVENTS_FLUSH_MS)
}
